-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id": "3492493f-bb5b-40f8-bae4-99b202ce8965", "shop": "CustomCurtainsStudio", "listing_id": "1723269690", "source_url": "https://www.etsy.com/listing/1723269690/check-patchwork-sheer-curtainfarmhouse", "category": "Sheer Curtains", "image_url": null, "destination_url": "https://www.etsy.com/listing/1723269690/check-patchwork-sheer-curtainfarmhouse", "title": "Check Patchwork Sheer Curtain, Farmhouse Light Filtering Crochet Drapes", "body": "Check Patchwork Sheer Curtain, Farmhouse Light Filtering Crochet Drapes Style: checkered, patchwork, farmhouse, crochet. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/38873964/r/il/d60cec/6064278961/il_794xN.6064278961_qdb8.jpg", "new_title": "Check and Crochet Sheer Curtain", "new_body": "Small checks and crochet lace bring a soft farmhouse detail to windows. This CustomCurtainsStudio curtain uses cotton and polyester. Check the listing for panel quantities, sizes and heading options.", "facebook_draft": "A light window refresh with checks and crochet lace from CustomCurtainsStudio. Explore sizes and heading options before ordering. https://www.etsy.com/listing/1723269690/check-patchwork-sheer-curtainfarmhouse", "board_id": "801218658646993070", "checked_at": "2026-10-18T02:15:23.928316+00:00", "visual_verified": true, "available": true}, {"queue_id": "6183b0c5-b22c-4517-aaba-b6971e0ca721", "shop": "FrenchStyleDecor", "listing_id": "1323800588", "source_url": "https://www.etsy.com/listing/1323800588/embroidered-white-cotton-victorian-apron", "category": "Vintage Aprons", "image_url": null, "destination_url": "https://www.etsy.com/listing/1323800588/embroidered-white-cotton-victorian-apron", "title": "Elegant Embroidered Cotton Victorian Apron With Lace", "body": "Elegant Embroidered Cotton Victorian Apron With Lace Style: victorian, embroidered, lace, vintage. Materials: cotton. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/33874695/r/il/60699e/6521220075/il_794xN.6521220075_tb5r.jpg", "new_title": "Embroidered Cotton Apron with Lace", "new_body": "Cotton, embroidery and lace give this FrenchStyleDecor apron a Victorian-inspired look. The seller notes a slim fit; check measurements before ordering. Explore the original Etsy listing for details.", "facebook_draft": "A vintage-inspired kitchen detail: this FrenchStyleDecor cotton apron features embroidery and lace. The design has a slim fit, so check the measurements first. https://www.etsy.com/listing/1323800588/embroidered-white-cotton-victorian-apron", "board_id": "801218658646993070", "checked_at": "2026-10-18T02:15:23.928525+00:00", "visual_verified": true, "available": true}, {"queue_id": "2e521037-b288-4705-a748-65d6090dff90", "shop": "GavinHome", "listing_id": "1306867898", "source_url": "https://www.etsy.com/listing/1306867898/white-sheer-curtain-embroidered-floral", "category": "Sheer Curtains", "image_url": null, "destination_url": "https://www.etsy.com/listing/1306867898/white-sheer-curtain-embroidered-floral", "title": "Romantic Sheer Curtain: Embroidered Floral Ruffles Drape, Rod Pocket", "body": "Romantic Sheer Curtain: Embroidered Floral Ruffles Drape, Rod Pocket Style: romantic, floral, embroidered, ruffle. Materials: polyester. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/36377996/r/il/9db4b8/5377234917/il_794xN.5377234917_k6ma.jpg", "new_title": "Floral Sheer Curtain with Ruffled Detail", "new_body": "Floral embroidery and ruffled details create a romantic window accent. This GavinHome sheer polyester curtain is made to order. Choose the panel quantity, size and heading style in the original listing.", "facebook_draft": "Add a floral detail to your windows with this GavinHome sheer curtain. Explore the listed sizes, panel quantities and heading options on Etsy. https://www.etsy.com/listing/1306867898/white-sheer-curtain-embroidered-floral", "board_id": "801218658646993070", "checked_at": "2026-10-18T02:15:23.928528+00:00", "visual_verified": true, "available": true}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text,facebook_draft text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status='draft' and cv.status='draft' and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id)
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 3 then raise exception 'Expected 3 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;

update products p set primary_image_url=x.new_image_url,original_image_urls=jsonb_build_array(x.new_image_url),source_payload=coalesce(p.source_payload,'{}'::jsonb)||jsonb_build_object('material_verification',jsonb_build_object('source_url',x.source_url,'verified_at',x.checked_at,'image_verified',true,'batch','daily-20261018-b4')) from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set image_url=x.new_image_url,title=x.new_title,body=x.facebook_draft
from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.shop_id=q.shop_id and cv.platform='facebook' and cv.status='draft'
and not exists(select 1 from publish_history h where h.content_variant_id=cv.id)
and not exists(select 1 from publish_queue fq where fq.content_variant_id=cv.id and fq.status<>'draft');

insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;


commit;
